Commit:     Brendan Abolivier <brendan@thunderbird.net>
CommitDate: Thu Aug 14 16:17:34 2025 +0000

    Bug 1957975 - Part 5: Modernise IEwsMessageFetchCallbacks and IEwsMessageCallbacks. r=edicharry

    Just like part 4, this patch does the following to `IEwsMessageFetchCallbacks`
    and `IEwsMessageCallbacks`:

    * Lambda-ified the implementations
    * Added missing documentation
    * Updated the interface and method names to make them more consistent with the
      new listeners and other existing listeners across the codebase (including
      merging methods when relevant)

    Differential Revision: https://phabricator.services.mozilla.com/D260693

diff --git a/mailnews/base/src/MsgOperationListener.h b/mailnews/base/src/MsgOperationListener.h
index bd83a6ce891..1f5cc265886 100644
--- a/mailnews/base/src/MsgOperationListener.h
+++ b/mailnews/base/src/MsgOperationListener.h
@@ -6,7 +6,10 @@
 #define COMM_MAILNEWS_BASE_SRC_MSGOPERATIONLISTENER_H_

 #include <functional>  // For std::function.
+
+#include "nsIMsgHdr.h"
 #include "nsIMsgOperationListener.h"
+#include "nsTArray.h"

 /**
  * MsgOperationListener is a small helper implementation of
@@ -15,19 +18,23 @@
 class MsgOperationListener : public nsIMsgOperationListener {
  public:
   NS_DECL_ISUPPORTS
-  using StopFunc = std::function<nsresult(nsresult)>;
+  using StopFunc =
+      std::function<nsresult(nsresult, const nsTArray<RefPtr<nsIMsgDBHdr>>&)>;

   MsgOperationListener() = delete;
-  explicit MsgOperationListener(StopFunc fn) : mStopFunc(fn) {
+  explicit MsgOperationListener(
+      const nsTArray<RefPtr<nsIMsgDBHdr>>& newMessages, StopFunc fn)
+      : mStopFunc(std::move(fn)), mNewMessages(newMessages.Clone()) {
     MOZ_ASSERT(mStopFunc);
   }

   NS_IMETHOD OnStopOperation(nsresult status) override {
-    return mStopFunc(status);
+    return mStopFunc(status, mNewMessages);
   }

  protected:
   StopFunc mStopFunc;
+  const nsTArray<RefPtr<nsIMsgDBHdr>> mNewMessages;
   virtual ~MsgOperationListener() {}
 };

